// src/data/blogCovers.ts
// ------------------------------------------------------------------
// PHASE 18 / S1 — resolves blog cover variants for the article template.
//
// The manifest is generated by tools/optimize-blog-covers.mjs during the
// build (before `astro build`) and is intentionally git-ignored, exactly
// like /public/images/optimized/. If it is missing (e.g. plain `astro
// dev` on a fresh clone) every cover simply falls back to the original
// JPEG — no srcset, no reserved space — instead of breaking the build.
// ------------------------------------------------------------------
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

type Variant = { width: number; avif: string; webp: string };
type Entry = { width: number; height: number; dir: string; variants: Variant[] };

// .article-content-wrapper max-width: 800px, .container padding 24px each side.
const SIZES = '(max-width: 848px) calc(100vw - 48px), 800px';
const MANIFEST_REL = 'src/data/blog-cover-manifest.json';

let cache: Record<string, Entry> | null = null;
let warned = false;

function manifest(): Record<string, Entry> {
  if (cache) return cache;
  try {
    cache = JSON.parse(readFileSync(join(process.cwd(), MANIFEST_REL), 'utf8'));
  } catch {
    cache = {};
    if (!warned) {
      warned = true;
      console.warn(
        `[blogCovers] ${MANIFEST_REL} not found — blog covers render the original JPEG only. ` +
          'Run `node tools/optimize-blog-covers.mjs` to generate variants.'
      );
    }
  }
  return cache as Record<string, Entry>;
}

export type BlogCover = {
  width: number;
  height: number;
  avifSrcset: string;
  webpSrcset: string;
  sizes: string;
};

export function getBlogCover(src?: string | null): BlogCover | null {
  if (!src) return null;
  const entry = manifest()[src];
  if (!entry || !entry.variants || entry.variants.length === 0) return null;
  const avifSrcset = entry.variants.map((v) => `${entry.dir}/${v.avif} ${v.width}w`).join(', ');
  const webpSrcset = entry.variants.map((v) => `${entry.dir}/${v.webp} ${v.width}w`).join(', ');
  return { width: entry.width, height: entry.height, avifSrcset, webpSrcset, sizes: SIZES };
}
